{
  "ruling": {
    "ruling": "FULL_REFUND",
    "amount_sgd": 4.0,
    "driver_compensation_sgd": null,
    "referrals": [
      "POL-NS-05(ii) — false-arrival record: record trip TRP-09104 (driver DRV-09104, 2026-09-04) as a false-arrival event against the driver, the arrival marker at 07:25:20 having been set more than 300 m from the pickup pin with no qualifying in-geofence fix anywhere in the trip."
